SELECT COALESCE(SUM(amount), 0)
FROM transactions
WHERE user_id = #{userId}
  AND category_id = #{categoryId}
  AND type = 'expense'
  AND status = 'success'
  AND occurred_at >= #{from}
  AND occurred_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
